from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells = []
            edge = False
            while q:
                y,x = q.popleft(); cells.append((y,x))
                if y == 0 or y == h-1 or x == 0 or x == w-1:
                    edge = True
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == bg and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            if not edge:
                ys=[y for y,x in cells]; xs=[x for y,x in cells]
                color = 7 if (max(ys)-min(ys)+1) % 2 else 2
                for y,x in cells: out[y][x] = color
    return out
